insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 2, 1, '{"place":"The mine, then the mill road","narrated":false,"tone":"wry","cupNight":true,"opener":"Beds are in the barn tonight. Pick a corner and take it.","questionTitle":"Did the takers know this valley before they rode into it?","forkA":"They were strangers here, guided only by the road.","forkB":"They knew every turn and every house.","callback":"The mine wall put Tamsin''s name first and Corin''s second. Tamsin heard them say \"the mill boy next\".","nudge":"{friend:Aim}, the cart came through in the dark without a lantern. What kind of driver does that?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How did the cart travel in the dark?","clickText":"The horse never checked or slowed in the pitch dark, yet walked straight past the old man''s gate without stopping. The driver knew exactly where he was going, and which house he wanted."},"clicks":[{"a":"2-1-1","b":"2-1-2","text":"The horse never checked or slowed in the pitch dark, yet walked straight past the old man''s gate without stopping. The driver knew exactly where he was going, and which house he wanted.","solves":true}],"riddle":null,"leads":[{"id":"2-1-1","place":"the bench by his door","actions":[{"attr":"Charm","verb":"let him tell it his own way"},{"attr":"Intellect","verb":"ask him about the horse, not the men"}],"clueTitle":"The steady horse","clueText":"The old man says the horse never balked at his gate or at the fork, in full dark and with no lamp. It took the mill lane at a steady walk.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-1-2","place":"the fresh ruts in the lane","actions":[{"attr":"Aim","verb":"follow the ruts past his gate"},{"attr":"Craft","verb":"read where the wheels ran"}],"clueTitle":"Past the gate","clueText":"The ruts run past his gate without a check. By that gate, in plain sight of the lane, a child''s wooden horse lies on its side in the grass.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-1-3","place":"where the cart turned upriver","actions":[{"attr":"Agility","verb":"run down to the turn before dark"},{"attr":"Aim","verb":"read the turn in the half-light"}],"clueTitle":"Deeper coming down","clueText":"Where the cart turned upriver, the ruts coming down sink deeper into the verge than the ruts going up.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"We held his last wall.\"* Whose wall, and why was it meant to fall?","weekQuestion":"Why these children, and not any others?","pull":"**The mill is an hour on. At first light: what did the family see?**"}'::jsonb),
('dark-moon', 1, 2, 2, '{"place":"The mill","narrated":false,"tone":"wry","cupNight":false,"opener":"Asked for by name, and by the night he was born. That''s an odd thing to ask for.","questionTitle":"How did they know which child was Corin?","forkA":"They carried a written record of who was born here.","forkB":"Someone who knows the family pointed him out.","callback":"In the mine, that shape was a hole, and what sat in it was gone. Here it''s cut into the mill''s footing.","nudge":"{friend:Craft}, boot-mud straight to the bed, and a paper in his fist. Where did that paper come from?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Did he hesitate once he reached the house?","clickText":"He checked the paper in his fist once at the door, then walked straight to the boy''s bed without a single wrong turn. He came with a name written down, and knew where that child slept."},"clicks":[{"a":"2-2-1","b":"2-2-2","text":"He checked the paper in his fist once at the door, then walked straight to the boy''s bed without a single wrong turn. He came with a name written down, and knew where that child slept.","solves":true}],"riddle":null,"leads":[{"id":"2-2-1","place":"the doorway, with her","actions":[{"attr":"Charm","verb":"ask her what was in his hands"},{"attr":"Intellect","verb":"ask her what he did before he spoke"}],"clueTitle":"The paper in his fist","clueText":"She says he had a folded paper in his fist. He looked at it once, then said the boy''s name.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-2-2","place":"inside the mill door","actions":[{"attr":"Aim","verb":"follow his boot-marks inside"},{"attr":"Craft","verb":"read the dried mud on the boards"}],"clueTitle":"Straight to the bed","clueText":"Nobody has swept since. His dried boot-mud goes from the door straight to the boy''s bed and back, and never turns aside.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-2-3","place":"the yard where the cart stood","actions":[{"attr":"Aim","verb":"walk the yard by the light from the door"},{"attr":"Craft","verb":"read what the horse left behind"}],"clueTitle":"The cropped grass","clueText":"Where the cart stood in the yard, the grass is cropped short in a wide half-circle, as far as a tethered horse can reach.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"By the third, we had stopped.\"* Why stop counting?","weekQuestion":"Why these children, and not any others?","pull":"**Upriver. The ruts are four nights old, and there is weather coming.**"}'::jsonb),
('dark-moon', 1, 2, 3, '{"place":"Upriver","narrated":false,"tone":"wry","cupNight":false,"opener":"A stranger dead at a lock, and a lock that opened for you. Rooms like that have opinions.","questionTitle":"Who was the stranger left dead at the housing?","forkA":"A seeker like us, trying to reach what is inside.","forkB":"A guard or look-out left to keep people away.","callback":"Corin was asked for by name. Today a lock that wouldn''t open for a dead man opened for you.","nudge":"{friend:Intellect}, a purse full of silver on a dead man''s belt. Why leave it?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Did he die on the day he reached the lock?","clickText":"He came back to that lock day after day with tools, and his purse is still heavy with silver. He was not killed for what he carried, and he was not killed in a hurry."},"clicks":[{"a":"2-3-1","b":"2-3-2","text":"He came back to that lock day after day with tools, and his purse is still heavy with silver. He was not killed for what he carried, and he was not killed in a hurry.","solves":true}],"riddle":null,"leads":[{"id":"2-3-1","place":"the stone round the housing","actions":[{"attr":"Craft","verb":"look at the stone round the lock"},{"attr":"Intellect","verb":"read the marks cut into it"}],"clueTitle":"The scratches","clueText":"The stone round the housing is scored with dozens of short scratches, some weathered and some bright. He tried it more than once, on more than one day.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"2-3-2","place":"the stranger on the path","actions":[{"attr":"Charm","verb":"kneel by him and close his eyes"},{"attr":"Intellect","verb":"go through what he carried"}],"clueTitle":"Silver in his purse","clueText":"His purse is still on his belt, and there is silver in it. A week of people have stepped over him, and not one has taken it.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"2-3-3","place":"the narrows where the dog lies","actions":[{"attr":"Might","verb":"hold the chain short and get past"},{"attr":"Aim","verb":"look past the dog from the rocks"}],"clueTitle":"The full pail","clueText":"Behind the dog, at the end of its chain, stands a pail of water, full and clean. There is a scrap of fresh meat beside it.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Ours was the last light burning.\"* The last of what?","weekQuestion":"Why these children, and not any others?","pull":"**Where was he trying to get to? The path goes on past him, and up.**"}'::jsonb),
('dark-moon', 1, 2, 4, '{"place":"The shaft in the hillside","narrated":false,"tone":"quiet","cupNight":false,"opener":"Sit down before you fall down.","questionTitle":"Did our footsteps at the shaft give us away?","forkA":"They heard the stone tumble down the shaft.","forkB":"They were waiting for us before we ever reached the lip.","callback":"Yesterday a branch swung on the slope with no wind. Today they knew you were at the shaft.","nudge":"{friend:Charm}, the heads turned below, but the chant ran on. What does that tell you?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"2-4-1","place":"the foot of the shaft","actions":[{"attr":"Aim","verb":"look down past the edge"},{"attr":"Agility","verb":"creep back to the lip and look"}],"clueTitle":"The second lamp","clueText":"A second lamp stands lit at the foot of the shaft, filled and trimmed, the same make as the ring in the chamber. Nobody grabbed it in a hurry.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"2-4-2","place":"the timbers at the shaft''s mouth","actions":[{"attr":"Craft","verb":"look over the timbering at the top"},{"attr":"Aim","verb":"follow the timber down by the lamplight"}],"clueTitle":"The pale scar","clueText":"On the timbering just below the top, a fresh pale scar runs down the wood, where a stone knocked loose went bouncing all the way to the bottom.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"2-4-3","place":"the voices down the shaft","actions":[{"attr":"Aim","verb":"lie flat at the edge and listen"},{"attr":"Intellect","verb":"count the voices as they go round"}],"clueTitle":"The chant ran on","clueText":"When the shout went up, the heads turned, but the chant never stopped. It ran on under the shout the whole time, the same few words.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"His hand was bleeding, and he told us to sleep.\"* What did he do down there?","weekQuestion":"Why these children, and not any others?","pull":"**Is there another way into this hill, before they finish? You have tonight to find it.**"}'::jsonb),
('dark-moon', 1, 2, 5, '{"place":"The hillside by night","narrated":false,"tone":"wry","cupNight":false,"opener":"A small black circle. Somebody wanted a thing forgotten, and somebody else wouldn''t let it be.","questionTitle":"Why was the king''s name erased from the stone?","forkA":"Erased by his enemies, so no one would rally to him.","forkB":"Erased by his own people, in shame or fear.","callback":"On Day 2 a horn button, on Day 3 a dead stranger. Tonight, a circle.","nudge":"{friend:Intellect}, why turn a carved stone with its face to the wall?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Were the stones broken or hidden?","clickText":"Some stones were shattered with fire and mallet, but the ones in the sheepfold were turned face-inward with care. The people here did not only destroy his name—they hid what they could not bear to lose."},"clicks":[{"a":"2-5-2","b":"2-5-3","text":"Some stones were shattered with fire and mallet, but the ones in the sheepfold were turned face-inward with care. The people here did not only destroy his name—they hid what they could not bear to lose.","solves":true}],"riddle":null,"leads":[{"id":"2-5-1","place":"the old stone where he signalled","actions":[{"attr":"Craft","verb":"run a hand over each face of it"},{"attr":"Aim","verb":"look at it side-on by the lamp"}],"clueTitle":"The ground-flat face","clueText":"On the old stone where the scout stood, one face has been ground flat, long ago. The chisel scars are weathered grey. Whatever was carved there is gone.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-5-2","place":"the scree below the stone","actions":[{"attr":"Agility","verb":"scramble down the scree"},{"attr":"Aim","verb":"search the scree by lamplight"}],"clueTitle":"Burned chips","clueText":"Mixed into the scree are chips of dressed stone, blackened by fire. One still carries the curve of a carved letter, broken off mid-word.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-5-3","place":"the fallen sheepfold","actions":[{"attr":"Might","verb":"lift the fallen stones one by one"},{"attr":"Craft","verb":"look at how the fold was built"}],"clueTitle":"Faces turned in","clueText":"The fold''s old cut stones were laid with their carved sides turned inward, against each other, every one. From outside, the wall shows nothing.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Not one of us who would not have died for him.\"* Who was he, to the people who wrote this?","weekQuestion":"Why these children, and not any others?","pull":"**There is no second door on this hillside, and now there is a clock. Last week, six cold slivers showed you a way nobody was watching. You have five.**"}'::jsonb),
('dark-moon', 1, 2, 6, '{"place":"The lip of the shaft","narrated":false,"tone":"wry","cupNight":true,"opener":"Digging toward an older room. You have to respect the effort.","questionTitle":"What are they digging for in the deep rock?","forkA":"To cut a way into the older chamber.","forkB":"To dig out something buried before the room was made.","callback":"In the mine, you reached the mark after it was emptied. Tonight they''re still digging toward the older room.","nudge":"{friend:Might}, two lamps, a steady line of picks, and baskets sifted by hand. What are they so afraid of missing?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How deep is their digging compared to our old way in?","clickText":"The pick-strokes drive in a single line toward the old chamber, and every basket of earth is sifted through bare fingers. They are not only clearing rock—they are searching for a specific thing."},"clicks":[{"a":"2-6-1","b":"2-6-2","text":"The pick-strokes drive in a single line toward the old chamber, and every basket of earth is sifted through bare fingers. They are not only clearing rock—they are searching for a specific thing.","solves":true}],"riddle":null,"leads":[{"id":"2-6-1","place":"the ground over the picks","actions":[{"attr":"Craft","verb":"feel the strokes through the turf"},{"attr":"Intellect","verb":"time the strokes and place them"}],"clueTitle":"One line","clueText":"The strokes come from one place only, and each new stroke lands a little nearer the old shaft than the last.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-6-2","place":"the two lamps at the foot","actions":[{"attr":"Aim","verb":"watch what passes the lamps"},{"attr":"Agility","verb":"crawl to the edge and look down"}],"clueTitle":"Sifted by hand","clueText":"In the lamplight at the foot of the shaft, baskets of dug earth are tipped out. Someone kneels and sifts each one through their hands before it is thrown aside.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-6-3","place":"the hole under the old stone","actions":[{"attr":"Might","verb":"shift one more stone"},{"attr":"Agility","verb":"squeeze in to the first step"}],"clueTitle":"Your own print","clueText":"Under the stones, the first step down is thick with dust. In the dust there is no print but your own.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"Morning came. The enemy did not.\"* Where did they go?","weekQuestion":"Why these children, and not any others?","pull":"**They are digging toward the old room. Be in it first.**"}'::jsonb)
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 3, 1, '{"place":"Somewhere warm","narrated":false,"tone":"wry","cupNight":false,"opener":"Somewhere warm. I''d settle for a warm supper. Eat.","questionTitle":"Did they take Wren to Ashcombe or beyond it?","forkA":"To Ashcombe, where her kin live.","forkB":"Ashcombe is only where they water their beasts on the way to the hills.","callback":"Corin was held a morning''s walk from his own mill. Wren was told she was going home first.","nudge":"{friend:Intellect}, a child''s mitten at Corin''s belt, and a water cask filled to the brim. Where is that road going?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Did the cart make ready for a long journey?","clickText":"They topped their water cask to the very brim and stood looking west toward the ridges before they started. They were preparing for the dry country, not a village visit."},"clicks":[{"a":"3-1-2","b":"3-1-3","text":"They topped their water cask to the very brim and stood looking west toward the ridges before they started. They were preparing for the dry country, not a village visit.","solves":true}],"riddle":null,"leads":[{"id":"3-1-1","place":"Corin, on the walk down","actions":[{"attr":"Charm","verb":"walk beside him and let him talk"},{"attr":"Aim","verb":"look him over in the morning light"}],"clueTitle":"The grey wool","clueText":"Corin has a child''s woollen mitten tucked in his belt that is not his. The wool is rough and grey, and it smells of sheep.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-1-2","place":"where the cart stood, below the shaft","actions":[{"attr":"Craft","verb":"read what the cart left in the grass"},{"attr":"Intellect","verb":"work out what they loaded"}],"clueTitle":"The full cask","clueText":"Where the cart stood, a cask has pressed a deep ring into the mud. The grass round it is soaked where they topped it up from the stream, right to the brim.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-1-3","place":"the shoulder of the hill he ran over","actions":[{"attr":"Agility","verb":"go up the shoulder after him"},{"attr":"Aim","verb":"follow his line from the shaft mouth"}],"clueTitle":"Facing west","clueText":"At the top of the shoulder the ground is scuffed where he stood a while, facing west. Then his prints go on, the same way the cart went.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Then they stopped being ours.\"* Whose were they, and what took them?","weekQuestion":"What do they need Wren for?","pull":"They are not hiding her. They told her she was going home.\n\n**Why would anyone take a stolen child back to where she was born? Ashcombe: a long day west.**"}'::jsonb),
('dark-moon', 1, 3, 2, '{"place":"Ashcombe","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"Why did Wren go with them without crying out?","forkA":"They were gentle with her and promised to bring her home.","forkB":"They threatened her people if she made a sound.","callback":"Tamsin and Corin each came home with one cut palm, bound clean. Wren''s taker said they''d only need her the once.","nudge":"{friend:Charm}, a sheepskin folded like a pillow in the cart, and hooves muffled with sacking. Why both?","nudgeIfLaid":null,"narratedSilence":"Garrick sits by the hearth with his boots off, watching the embers in silence.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"3-2-1","place":"the well, and the board of chips","actions":[{"attr":"Charm","verb":"crouch by the board and wait"},{"attr":"Aim","verb":"watch the well from across the street"}],"clueTitle":"The boy at the well","clueText":"At the well a boy holds his chip out low and quick, then shoves it back into his shirt before you have looked at it properly.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-2-2","place":"the empty cart at the foot of the black road","actions":[{"attr":"Craft","verb":"climb up and look over the boards"},{"attr":"Intellect","verb":"go over the cart end to end"}],"clueTitle":"The made bed","clueText":"In the bed of the empty cart a sheepskin is spread over the boards, and a blanket is folded at one end like a pillow.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-2-3","place":"the street, where every door shut","actions":[{"attr":"Aim","verb":"walk the street with your eyes on the ground"},{"attr":"Craft","verb":"pick out what is caught between the stones"}],"clueTitle":"Sacking on the stones","clueText":"Caught between the stones down the middle of the street are scraps of sacking. It is the kind men tie over hooves to quiet them on a night road.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"Remember that, when you hear where else we stood.\"* Where else might they have stood?","weekQuestion":"What do they need Wren for?","pull":"**What does anyone need a child for, once? The Blackglass: half a day up the black road, the place Meira marked.**"}'::jsonb),
('dark-moon', 1, 3, 3, '{"place":"The Blackglass","narrated":false,"tone":"wry","cupNight":false,"opener":"Mind your hands on that glass, all of you.","questionTitle":"Why did the riders pass the Blackglass mark without stopping?","forkA":"They already had what they needed from this stone.","forkB":"This stone was never the one they were looking for.","callback":"At the Widow''s Tooth a man lay in the bracken watching the rock. Here the riders went past this one without slowing.","nudge":"{friend:Intellect}, six horses on the ridge, and not one slowed for the ancient mark. Why?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Has anyone touched this housing since the road was made?","clickText":"The old shepherds'' path ends dead at the sunken stones, and the dust on the housing had no mark until your own fingers touched it. The riders did not even dismount here."},"clicks":[{"a":"3-3-1","b":"3-3-2","text":"The old shepherds'' path ends dead at the sunken stones, and the dust on the housing had no mark until your own fingers touched it. The riders did not even dismount here.","solves":true}],"riddle":null,"leads":[{"id":"3-3-1","place":"where the shepherds'' path meets the glass","actions":[{"attr":"Intellect","verb":"look at where the path gives out"},{"attr":"Agility","verb":"walk the edge of the glass"}],"clueTitle":"The row of stones","clueText":"Where the shepherds'' path meets the glass, a row of old stones lies across it, sunk deep in the turf. The path stops dead at the row.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"3-3-2","place":"the housing beside the mark","actions":[{"attr":"Craft","verb":"run a finger round its carving"},{"attr":"Intellect","verb":"look it over before you step away"}],"clueTitle":"Only your hand","clueText":"The glass round the housing is dull with fine dust. The only marks in it are the ones your own hand just made.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"3-3-3","place":"the far edge, where the glass is cracked","actions":[{"attr":"Aim","verb":"look back the way you came"},{"attr":"Might","verb":"climb onto the highest lip of glass"}],"clueTitle":"The view down","clueText":"From the far edge you can see all the way down the black road to Ashcombe''s roofs, and the well in the middle of them.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"He only never told us the price.\"* The price of what?","weekQuestion":"What do they need Wren for?","pull":"**They rode straight past the one thing Meira marked. So what are they riding to? On, into the black ridges.**"}'::jsonb),
('dark-moon', 1, 3, 4, '{"place":"The black ridges","narrated":false,"tone":"wry","cupNight":true,"opener":"She''s leaving chips on the trail. Clever girl.","questionTitle":"Who did Wren leave her glass chips for?","forkA":"For anyone following to find her.","forkB":"To mark her own trail so she could find the way back.","callback":"Tamsin wasn''t asleep; she was counting. Wren is dropping her chips, one by one, on their trail.","nudge":"{friend:Agility}, tiny scratches on the back of each chip: one, two, three. That''s a girl with her wits about her.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Did she drop the chips in haste or with care?","clickText":"Each chip was set on high bare rock where it would catch the light, and each back is numbered with tiny knife-scratches. She was counting her trail step by step."},"clicks":[{"a":"3-4-1","b":"3-4-3","text":"Each chip was set on high bare rock where it would catch the light, and each back is numbered with tiny knife-scratches. She was counting her trail step by step.","solves":true}],"riddle":null,"leads":[{"id":"3-4-1","place":"the rises along the riders'' trail","actions":[{"attr":"Aim","verb":"look back down the trail from the last rise"},{"attr":"Agility","verb":"run the trail back to the first chip"}],"clueTitle":"On the bare rock","clueText":"Each chip lay on bare rock at the top of a rise, never down in the ash where it would sink. Coming up behind, you see each one glint before you reach it.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"3-4-2","place":"the bone-white trees along the trail","actions":[{"attr":"Intellect","verb":"set each chip beside what stood near it"},{"attr":"Aim","verb":"look round from where each one lay"}],"clueTitle":"A tree at each","clueText":"Each chip lay a few paces from a dead tree, the tallest one in sight. Stand at one tree, and you can see the next.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"3-4-3","place":"the three chips in your hand","actions":[{"attr":"Craft","verb":"turn each one over in the light"},{"attr":"Intellect","verb":"lay them out side by side"}],"clueTitle":"Scratched on the back","clueText":"Turn the chips over. One has a single short scratch on its back, one has two, and one has three.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We locked with what we are.\"* What are they?","weekQuestion":"What do they need Wren for?","pull":"**She is alive, and she is thinking. The hut, at first light.**"}'::jsonb),
('dark-moon', 1, 3, 5, '{"place":"The shepherd''s hut","narrated":false,"tone":"wry","cupNight":false,"opener":"That was an empty hut. Come nearer the fire.","questionTitle":"Why did they leave the hut in the middle of the night?","forkA":"They were warned that we were coming up the ridge.","forkB":"The hour they were waiting for arrived.","callback":"At the mine someone took the time to bind Tamsin''s hand in clean linen. Here someone folded one blanket with care, and threw the other down.","nudge":"{friend:Craft}, one bed neatly made, one water skin dropped in the grass. What made them move?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How quickly did they depart?","clickText":"Her name on the door was cut with patient double strokes, but by the spring a full water skin lies dropped with its stopper loose. They took their time until a single moment—then moved all at once."},"clicks":[{"a":"3-5-1","b":"3-5-2","text":"Her name on the door was cut with patient double strokes, but by the spring a full water skin lies dropped with its stopper loose. They took their time until a single moment—then moved all at once.","solves":true}],"riddle":null,"leads":[{"id":"3-5-1","place":"low on the doorframe","actions":[{"attr":"Craft","verb":"run a thumbnail along the letters"},{"attr":"Intellect","verb":"look at how each letter was made"}],"clueTitle":"Cut twice","clueText":"Each stroke of the name has been cut twice, the second pass deeper than the first.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-5-2","place":"the spring below the hut","actions":[{"attr":"Agility","verb":"get down to the water fast"},{"attr":"Aim","verb":"look over the ground by the spring"}],"clueTitle":"The dropped skin","clueText":"By the spring a water skin lies in the grass, half full. Its stopper is a pace away.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"3-5-3","place":"the wall beside the pallet","actions":[{"attr":"Charm","verb":"sit on the pallet and look round"},{"attr":"Intellect","verb":"look at what is kept by the bed"}],"clueTitle":"The gap in the row","clueText":"Along the wall by the pallet, small things are set out in a row: a twist of grey wool, a white pebble, a hen''s feather. At one end there is a gap, and the dust there is clean.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"That is why kingdoms fear them.\"* Why would a kingdom fear a family?","weekQuestion":"What do they need Wren for?","pull":"**A step, now, and no more. If they could see you, can you see them? The cairn on the highest ridge, before the light goes.**"}'::jsonb),
('dark-moon', 1, 3, 6, '{"place":"The cairn","narrated":false,"tone":"wry","cupNight":false,"opener":"Fire''s built up. Sit by it before you decide anything.","questionTitle":"What is happening inside the Kiln tonight?","forkA":"A ritual that requires the child''s presence.","forkB":"They are hiding her until the way north opens.","callback":"Corin said Wren''s home was always warm. Tonight the map ends at a hill that breathes warm air.","nudge":"{friend:Aim}, the lamp climbed the hill and went out inside. What does that crack breathe out?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Are the riders still inside the hill?","clickText":"No horses wait outside, and thin pale smoke rises from the crown where by day the air only shimmered. The men are inside the hill, and the fire in the Kiln has been lit."},"clicks":[{"a":"3-6-1","b":"3-6-2","text":"No horses wait outside, and thin pale smoke rises from the crown where by day the air only shimmered. The men are inside the hill, and the fire in the Kiln has been lit.","solves":true}],"riddle":null,"leads":[{"id":"3-6-1","place":"the foot of the round hill","actions":[{"attr":"Aim","verb":"look down at the foot of the hill"},{"attr":"Intellect","verb":"go over every shape below the crown"}],"clueTitle":"No horses","clueText":"Not one horse is tethered at the foot of the Kiln.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-6-2","place":"the crack across its crown","actions":[{"attr":"Aim","verb":"watch the crown after the lamp goes in"},{"attr":"Intellect","verb":"watch the air over the crack"}],"clueTitle":"Smoke from the crack","clueText":"Soon after the lamp goes in, thin pale smoke starts to rise from the crack. By daylight there was only shimmering air.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"3-6-3","place":"the knife-edge below the cairn","actions":[{"attr":"Agility","verb":"go a little way back along the edge"},{"attr":"Might","verb":"test the stones of the face"}],"clueTitle":"No way down in the dark","clueText":"Now the light has gone, the knife-edge below the cairn is a black line with nothing either side. The face beside it drops straight to loose scree.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"We never dug him a grave.\"* Why not?","weekQuestion":"What do they need Wren for?","pull":"**Whatever happens under that hill has started. Into the Kiln, tonight.**"}'::jsonb)
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 4, 1, '{"place":"Under the Kiln, then Ashcombe","narrated":false,"tone":"wry","cupNight":false,"opener":"Count yourselves. I will, too.","questionTitle":"Did someone inside the room help cut the prisoner loose?","forkA":"Yes, an accomplice was waiting in the shadows.","forkB":"No, he had a blade palmed and worked his own bonds.","callback":"Every one of them you''ve fought has run at the first gap. Tonight one stood among you with a blade and cut only rope.","nudge":"{friend:Craft}, cut rope ends all clean on the same side. That wasn''t a man sawing at his own wrists.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Was someone waiting in the side passage?","clickText":"The passage smells of a freshly snuffed wick, and every rope was severed by a blade cutting from the same outside angle. Someone was waiting in the dark with steel ready."},"clicks":[{"a":"4-1-1","b":"4-1-3","text":"The passage smells of a freshly snuffed wick, and every rope was severed by a blade cutting from the same outside angle. Someone was waiting in the dark with steel ready.","solves":true}],"riddle":null,"leads":[{"id":"4-1-1","place":"the passage none of you had noticed","actions":[{"attr":"Agility","verb":"go a few steps in, without a lamp"},{"attr":"Intellect","verb":"stand in its mouth and take stock"}],"clueTitle":"The snuffed wick","clueText":"A few steps into the passage the air smells of a wick just put out. None of your lamps has been in there.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-1-2","place":"the place where he knelt","actions":[{"attr":"Aim","verb":"pace it out from the passage"},{"attr":"Intellect","verb":"work out what he could reach from there"}],"clueTitle":"Three paces","clueText":"Where he knelt is three paces from the passage mouth, in the corner your lamps lit least.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-1-3","place":"the ropes on the stone","actions":[{"attr":"Craft","verb":"lay the cut ends side by side"},{"attr":"Might","verb":"pick them up and test each one"}],"clueTitle":"The same side","clueText":"Every rope is cut a finger''s width from its knot, and every cut is on the same side.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"To hold what needed five.\"* What needed holding, and what is the last lock?","weekQuestion":"What do they need Joss for?","pull":"*Already with us.* Joss is not waiting to be taken.\n\n**A blade within arm''s reach, in the dark, and it cut rope. Why are you still alive? The north road, at first light.**"}'::jsonb),
('dark-moon', 1, 4, 2, '{"place":"The north road","narrated":false,"tone":"wry","cupNight":true,"opener":"Cold road. Put your hands round that cup.","questionTitle":"Why did four riders carry a cart along the open highway?","forkA":"They were daring anyone to challenge them.","forkB":"They were escorting something too heavy or fragile for rough paths.","callback":"The carter''s coin has the king''s face scraped off. Meira wrote that every record of him had been scraped clean.","nudge":"{friend:Intellect}, swords across their laps and eyes never leaving the cart-bed. What was under that canvas?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How did the riders conduct themselves through the settlements?","clickText":"They rode with drawn swords across their laps in broad daylight, yet not one rider looked at the road or the bystanders. Every eye was locked on what was inside that cart."},"clicks":[{"a":"4-2-1","b":"4-2-2","text":"They rode with drawn swords across their laps in broad daylight, yet not one rider looked at the road or the bystanders. Every eye was locked on what was inside that cart.","solves":true}],"riddle":null,"leads":[{"id":"4-2-1","place":"the carter, watering his horses","actions":[{"attr":"Charm","verb":"let him run on about the riders"},{"attr":"Intellect","verb":"ask how the four rode"}],"clueTitle":"Every eye on the cart","clueText":"The carter says the four never spoke to each other, and never once looked at the road or the lake. Every eye stayed on the cart.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-2-2","place":"the men in the shallows","actions":[{"attr":"Charm","verb":"sit down in the water with them"},{"attr":"Intellect","verb":"ask what made them let it pass"}],"clueTitle":"Blades bare","clueText":"They say the four came through the ford with their blades bare across their saddles, in full daylight, and did not slow down.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-2-3","place":"the ruts going north","actions":[{"attr":"Aim","verb":"follow them as far as the light lets you"},{"attr":"Craft","verb":"read where they could have turned off"}],"clueTitle":"The open road","clueText":"Their ruts keep to the open road the whole way, past every shepherd''s hut. A sheep-path along the ridge would have hidden them from all of it.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"The fifth had no element at all.\"* What could it be, if it is not earth, wind, water or fire?","weekQuestion":"What do they need Joss for?","pull":"**Four armed men for one small box, riding away from the boy. What is in it? Reedham, by noon tomorrow.**"}'::jsonb),
('dark-moon', 1, 4, 3, '{"place":"Reedham","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"Why do oars cross the lake to the tower every night at dusk?","forkA":"Taking food and supplies to a guarded prisoner.","forkB":"Watching for the dark-moon hour when the water drops.","callback":"In Ashcombe a baby born when the moon goes out is given a chip of black glass. In Reedham every window is lit for one.","nudge":"{friend:Craft}, oil drops leading to one door on the shingle, and oars at dusk every night. Who is keeping watch on whom?","nudgeIfLaid":null,"narratedSilence":"Garrick sits by the window looking out over the water, his arms folded in the quiet room.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"4-3-1","place":"the fisherman on the shingle","actions":[{"attr":"Charm","verb":"help him with his nets and listen"},{"attr":"Intellect","verb":"ask what he hears at night"}],"clueTitle":"The oars at dusk","clueText":"On the shingle the fisherman says he hears oars out on the lake every night, at the same hour, just after dusk. He has never gone to look.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"4-3-2","place":"the lane up from the water","actions":[{"attr":"Aim","verb":"walk the lane up from the shingle"},{"attr":"Intellect","verb":"look at every door you pass"}],"clueTitle":"One door","clueText":"Small dark spots of lamp-oil stain the stones of the lane, a pace apart. They go up to her door and back, and to no other door.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"4-3-3","place":"the tower''s lowest window","actions":[{"attr":"Agility","verb":"climb up to the sill from the skiff"},{"attr":"Aim","verb":"look it over from the water"}],"clueTitle":"A cleared sill","clueText":"On the tower''s lowest sill, on the side facing Reedham, the weed is scraped away in a patch the size of a seat. From there you can see her window.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"So does anyone born in its dark.\"* What does a child born in the dark have in common with what fell?","weekQuestion":"What do they need Joss for?","pull":"Back on the shingle, beside the place her skiff was lying, there are keel-marks that are not hers. Fresh ones, pressed deep into the wet stones, and the lapping of the lake has not yet smoothed them.\n\nUp the lane, the lamp burns on in her window, small and steady in the afternoon.\n\n**Someone has been rowing out to the drowned village by night. Old Reedham, at the shallow end, tomorrow.**"}'::jsonb),
('dark-moon', 1, 4, 4, '{"place":"Old Reedham","narrated":false,"tone":"wry","cupNight":false,"opener":"Meira had a gloss for it: ''the old songs'' word for the marked.'' She was careful with her words.","questionTitle":"What does ''moon-blood'' mean in Meira''s notes?","forkA":"Children born during an eclipse or dark moon.","forkB":"An ancient bloodline that has carried down through the valleys.","callback":"At the ford, Tamsin''s small prints stopped at the water. Today Joss''s stop at the edge of deep water.","nudge":"{friend:Intellect}, she started a second line in the margin, then crossed it out so hard the nib went through. What did she realize?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Did Meira treat ''the marked'' and ''moon-blood'' as the same thing?","clickText":"Meira copied ''the marked'' and ''moon-blood'' from two separate sources centuries apart, then struck her own comparison out until the paper tore. Even she realized they were not the same thing."},"clicks":[{"a":"4-4-2","b":"4-4-3","text":"Meira copied ''the marked'' and ''moon-blood'' from two separate sources centuries apart, then struck her own comparison out until the paper tore. Even she realized they were not the same thing.","solves":true}],"riddle":null,"leads":[{"id":"4-4-1","place":"the drowned windows","actions":[{"attr":"Aim","verb":"look along the windows in the low light"},{"attr":"Craft","verb":"look at the iron in each frame"}],"clueTitle":"The old hooks","clueText":"In every drowned window frame is the same iron lamp-hook that hangs in Reedham''s windows today. Each one is black with old soot.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"4-4-2","place":"the earlier pages of her notes","actions":[{"attr":"Intellect","verb":"go back through them, page by page"},{"attr":"Craft","verb":"set the copied hands side by side"}],"clueTitle":"Two records","clueText":"Two pages back, she copied \"the marked\" out of a different record. The two words never appear in the same copied line.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"4-4-3","place":"the margin of her page","actions":[{"attr":"Intellect","verb":"read her note against the line"},{"attr":"Aim","verb":"hold the page to the lamp"}],"clueTitle":"The scratched line","clueText":"Under her note she began a second line, then scratched it out so hard the nib went through the paper.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"Moon-blood woke it once.\"* What did it wake, and when?","weekQuestion":"What do they need Joss for?","pull":"**A warning against what? The reed island, a mile out: the only place on this lake a boat can put in unseen.**"}'::jsonb),
('dark-moon', 1, 4, 5, '{"place":"The reed island","narrated":false,"tone":"wry","cupNight":false,"opener":"Pale curls of whittled wood. Somebody''s still carving.","questionTitle":"Why do they let Joss carve while they hold him?","forkA":"To keep his hands busy so he doesn''t try to escape.","forkB":"His carving has something to do with the stones or the water.","callback":"At the Widow''s Tooth a little carved horse was left behind. Today, in their boat, a little carved hull was thrown away.","nudge":"{friend:Aim}, three willow cuts—one grey, one brown, one white. Three days he sat there whittling.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How long was he kept on that reed island?","clickText":"The willow has had fresh shoots cut three days running, and the shavings in the bilge were carved without haste. He was held on that island for days, unhurried and unharmed."},"clicks":[{"a":"4-5-1","b":"4-5-3","text":"The willow has had fresh shoots cut three days running, and the shavings in the bilge were carved without haste. He was held on that island for days, unhurried and unharmed.","solves":true}],"riddle":null,"leads":[{"id":"4-5-1","place":"the rope in the bottom of their boat","actions":[{"attr":"Craft","verb":"sift the shavings out of the rope"},{"attr":"Intellect","verb":"look at how each one was cut"}],"clueTitle":"Long curls","clueText":"Every curl in the bottom of the boat is long and unbroken, and all of them are fresh. Nobody hurried him.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-5-2","place":"the stern seat","actions":[{"attr":"Craft","verb":"feel under the thwart"},{"attr":"Might","verb":"lift the seat board out"}],"clueTitle":"Folded dry","clueText":"Under the stern seat, out of the spray, a blanket is folded small. It is dry.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"4-5-3","place":"the willows at the water''s edge","actions":[{"attr":"Agility","verb":"work along the bank through the willows"},{"attr":"Craft","verb":"look at where the wood was cut"}],"clueTitle":"Three shoots","clueText":"One willow has had three straight shoots cut from it with a sharp blade. One cut is grey, one is brown, and one is still white.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Pray no one ever learns it is also a door.\"* A door to what, and who would want it opened?","weekQuestion":"What do they need Joss for?","pull":"**Why would anyone keep watch on an empty tower? After that lamp, tonight, in their own boat.**"}'::jsonb),
('dark-moon', 1, 4, 6, '{"place":"The tower at night","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"Was the boat under the tower waiting for us or for them?","forkA":"An Order patrol guarding the flooded causeway.","forkB":"A watcher posted to see who answered the call.","callback":"Yesterday you took their boat. Tonight someone took your words.","nudge":"{friend:Aim}, water rings spreading under the stones while our oars were already still. Someone was down there before us.","nudgeIfLaid":null,"narratedSilence":"Garrick stands in the doorway looking out into the mist where the water laps at the wall.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"4-6-1","place":"the dark water under the wall","actions":[{"attr":"Aim","verb":"watch the water as you tie up"},{"attr":"Agility","verb":"lean out over the stones"}],"clueTitle":"The rings","clueText":"As you tie up at the tower, rings are already spreading from the dark under its wall, and your oars have been still for a minute.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-6-2","place":"the empty windows of the bell-chamber","actions":[{"attr":"Aim","verb":"look back the way you came"},{"attr":"Intellect","verb":"watch the water you crossed"}],"clueTitle":"One light","clueText":"Out toward the island, low on the water, a light shows for a breath and goes out. It does not show again.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"4-6-3","place":"the lights of Reedham","actions":[{"attr":"Aim","verb":"pick out every light on the shore"},{"attr":"Charm","verb":"watch the shore with the others, quietly"}],"clueTitle":"The lamp on the shingle","clueText":"Down on the shore, one lamp moves slowly along the shingle. It stops below her lane, and stays there.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We never asked what that would make them.\"* What has it made them?","weekQuestion":"What do they need Joss for?","pull":"**Down the stair, into the boat you took from them, and after that sound. Now.**"}'::jsonb)
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 5, 1, '{"place":"Reedham, and the waystone","narrated":false,"tone":"wry","cupNight":false,"opener":"North, then. That''s a long road for tired boots.","questionTitle":"Why was the fifth name chiselled out of the waystone?","forkA":"To hide the existence of a fifth Stone altogether.","forkB":"Because the fifth Stone was taken by someone who broke from the rest.","callback":"Meira looked for a fifth and never found one. Today, on the road north, somebody had cut a line out of a stone.","nudge":"{friend:Intellect}, four names weathered by rain, and the fifth cut away clean. Who had the chisel?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Was the fifth Stone''s hiding place cold like the others?","clickText":"The name was cut out with crisp chisel strokes, yet the crack at the waystone''s foot retains the same unnatural rime you felt at every Seeker shrine. The place was real, even if its name was expunged."},"clicks":[{"a":"5-1-1","b":"5-1-2","text":"The name was cut out with crisp chisel strokes, yet the crack at the waystone''s foot retains the same unnatural rime you felt at every Seeker shrine. The place was real, even if its name was expunged.","solves":true}],"riddle":null,"leads":[{"id":"5-1-1","place":"the worn face of the waystone","actions":[{"attr":"Craft","verb":"run a thumb along the cut-away line"},{"attr":"Intellect","verb":"hold the light low and look at its edges"}],"clueTitle":"The crisp edge","clueText":"Frost has eaten the old carving, but the edges of the cut-out line are crisp. Not one letter of it is left.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-1-2","place":"the crack at the waystone''s foot","actions":[{"attr":"Craft","verb":"scrape back the rime with a knife"},{"attr":"Aim","verb":"watch the crack while the beat comes"}],"clueTitle":"The rime stays","clueText":"Long after the fragment is out, the rime stays in the crack, in a mild wind. It is the same cold you have felt at every hiding place since the forest road.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-1-3","place":"the lane up from the shingle","actions":[{"attr":"Charm","verb":"walk up the lane and stop at a door"},{"attr":"Aim","verb":"look up the lane from the boat"}],"clueTitle":"Every window lit","clueText":"Every window up the lane has a lamp burning at midday, as Reedham does only on a dark-moon night.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Then it began to take.\"* Take what, and from whom?","weekQuestion":"What will it take for the fifth to end this?","pull":"You stay that night in Reedham. Up the lane, the lamp burns on in her window.\n\nAt dusk the heartbeat comes again, up through the floorboards and into the legs of your chair. It is louder than it was at dawn.\n\n**What is left in a city where nothing grows and nobody goes? The old kingdom''s road: two days north.**"}'::jsonb),
('dark-moon', 1, 5, 2, '{"place":"The old kingdom''s road","narrated":false,"tone":"wry","cupNight":false,"opener":"The grass on a war grave shouldn''t shiver. I''d say that''s the heartbeat.","questionTitle":"What is driving the wild beasts against the travellers?","forkA":"The heartbeat from the north maddens them with fear.","forkB":"They are drawn to the blood of the marked children.","callback":"On the Stillwater the birds went quiet at the first beat. Tonight the dogs came with it.","nudge":"{friend:Might}, one bite through the linen, and tracks that scattered the moment the beat died. What did those beasts hear?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How did the pack behave when the tremor passed?","clickText":"When the subterranean beat sounded, the hounds froze in unison; the moment it ceased, they broke into wild scatter. They are not hunting under a master''s will—they are terrified out of their wits."},"clicks":[{"a":"5-2-1","b":"5-2-3","text":"When the subterranean beat sounded, the hounds froze in unison; the moment it ceased, they broke into wild scatter. They are not hunting under a master''s will—they are terrified out of their wits.","solves":true}],"riddle":null,"leads":[{"id":"5-2-1","place":"the edge of the dark, past the cart","actions":[{"attr":"Aim","verb":"watch them at the edge of the dark"},{"attr":"Might","verb":"stand over the cart and hold your ground"}],"clueTitle":"Heads down","clueText":"When the beat stops, every dog stops with it, heads down, mid-stride. Not one runs away, and not one comes on.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-2-2","place":"the bandage on the man''s forearm","actions":[{"attr":"Charm","verb":"ask to see the arm"},{"attr":"Craft","verb":"tie the bandage again, properly"}],"clueTitle":"One bite","clueText":"Under the bandage is a single bite, deep and clean. The teeth went in once and held, and nothing tore.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-2-3","place":"where the dogs came out of the dusk","actions":[{"attr":"Aim","verb":"read the ground at first light"},{"attr":"Intellect","verb":"walk their tracks back the way they came"}],"clueTitle":"Scattered","clueText":"At first light their tracks come in together, in a straight line from the north. They go out scattered every way, the prints far apart.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"That is why it had to be us.\"* Had to be them, for what?","weekQuestion":"What will it take for the fifth to end this?","pull":"**The heartbeat is nearer every dusk, and it is coming from inside the city. Highwall, by noon.**"}'::jsonb),
('dark-moon', 1, 5, 3, '{"place":"The herald''s gate","narrated":false,"tone":"wry","cupNight":false,"opener":"A bar of new timber in brackets worn bright. Somebody''s been barring this gate for centuries, and the wood''s new.","questionTitle":"Why is there a new timber bar on an ancient ruined gate?","forkA":"The Order barred it to keep intruders from entering Highwall.","forkB":"The people inside barred it to keep whatever is waking from getting out.","callback":"Upriver, somebody kept a hidden path clear and a dog on new iron. Here somebody keeps a new bar on an old gate.","nudge":"{friend:Craft}, fresh wood in old iron brackets. Somebody went to the trouble of felling an ash tree to bar that gate.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How recently was this gateway fortified?","clickText":"The timber bar was hewn within days, its cut ends still bright white, and a single narrow path has been trodden from it up into the city. Highwall has seen fresh boots this very week."},"clicks":[{"a":"5-3-1","b":"5-3-2","text":"The timber bar was hewn within days, its cut ends still bright white, and a single narrow path has been trodden from it up into the city. Highwall has seen fresh boots this very week.","solves":true}],"riddle":null,"leads":[{"id":"5-3-1","place":"the street behind the gate","actions":[{"attr":"Aim","verb":"look down into the street from the walkway"},{"attr":"Agility","verb":"lean out over the inner parapet"}],"clueTitle":"One trodden path","clueText":"In the dust of the street behind the gate, one narrow path is trodden from the bar up the hill, toward the smoke.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"5-3-2","place":"the near end of the new bar","actions":[{"attr":"Aim","verb":"pick out the bar''s end from above"},{"attr":"Craft","verb":"judge the timber by its colour"}],"clueTitle":"Still white","clueText":"The bar''s cut end is still white, and the axe-marks are sharp. It was put up within the last few days.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"5-3-3","place":"the broken stair","actions":[{"attr":"Agility","verb":"climb down to the gap in the stair"},{"attr":"Craft","verb":"look at the broken edges"}],"clueTitle":"Knocked out","clueText":"The missing steps lie at the stair''s foot in big, square pieces. Every break shows the bite of a hammer, weathered smooth.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"None of us gave to the fifth.\"* Why give to four and not to the fifth?","weekQuestion":"What will it take for the fifth to end this?","pull":"You spend the night up on the wall-walk, in the lee of the parapet, with the barred gate beneath you and that one thread of smoke going up into the dark.\n\n**Who bars a dead city from the inside, year after year? Down into the streets, following the wall.**"}'::jsonb),
('dark-moon', 1, 5, 4, '{"place":"The dead streets","narrated":false,"tone":"quiet","cupNight":true,"opener":null,"questionTitle":"Are the armoured figures in the streets alive or dead?","forkA":"Statues or corpses frozen by an ancient ward.","forkB":"Sentinels waiting for the final night of the count.","callback":"On the road, when the beat stopped, the dogs stopped where they stood. These soldiers stopped mid-stride, and never started again.","nudge":"{friend:Aim}, left foot forward on every single one, and not a print in the dust round their boots. What stopped them mid-stride?","nudgeIfLaid":null,"narratedSilence":"Garrick sets the extra cup on the cobbles by the empty doorway and leans against the doorpost in the dark.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"5-4-1","place":"the ground round the soldiers","actions":[{"attr":"Aim","verb":"look at the street round them"},{"attr":"Craft","verb":"crouch and look at the dust"}],"clueTitle":"Unbroken dust","clueText":"Round every boot the dust lies in one even skin. The only prints in it are yours.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"5-4-2","place":"the barred door of the empty house","actions":[{"attr":"Aim","verb":"keep an eye to the crack in the door"},{"attr":"Agility","verb":"sit by the door, ready, and listen"}],"clueTitle":"Metal on stone","clueText":"As the light goes, one sound comes from the direction of the street of soldiers: metal on stone, once. Then nothing.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"5-4-3","place":"the helms down the street","actions":[{"attr":"Aim","verb":"look along the line of helms"},{"attr":"Intellect","verb":"set each helm against the next"}],"clueTitle":"No two alike","clueText":"Every helm sits a little crooked on its neck, this way or that, no two the same. From the end of the street, any one of them could look turned.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"We could not bring ourselves to break them.\"* Why not?","weekQuestion":"What will it take for the fifth to end this?","pull":"**Was that helm turned before? Nobody is sure. And the smoke is higher up the hill. The square below the hall.**"}'::jsonb),
('dark-moon', 1, 5, 5, '{"place":"Below the hall","narrated":false,"tone":"wry","cupNight":false,"opener":"One chalk stroke each dusk. Somebody''s counting.","questionTitle":"What happens when the tally on the wall reaches zero?","forkA":"The doors of the great hall unlock.","forkB":"The king opens his eyes.","callback":"At Reedham they kept Joss eight nights, waiting for something. Here they strike off one night every dusk.","nudge":"{friend:Intellect}, one hand drew every stroke on that board. How long has he been standing at that chalk?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Who is keeping the vigil around the fire?","clickText":"Every mark on the tally was drawn by the same steady hand, and every robed head turns as one when the underground tremor pulses. They are not waiting in doubt—they are counting down to a certainty."},"clicks":[{"a":"5-5-1","b":"5-5-2","text":"Every mark on the tally was drawn by the same steady hand, and every robed head turns as one when the underground tremor pulses. They are not waiting in doubt—they are counting down to a certainty.","solves":true}],"riddle":null,"leads":[{"id":"5-5-1","place":"the board propped by the wall","actions":[{"attr":"Aim","verb":"read the board from the rubble"},{"attr":"Agility","verb":"creep close enough to see the chalk"}],"clueTitle":"One hand","clueText":"Every stroke on the board is in the same thick, square hand, the crossed ones and the ones still to cross. The chalk has been gone over many times, never redrawn.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-5-2","place":"the hooded figures at the fire","actions":[{"attr":"Aim","verb":"watch their faces from the rubble"},{"attr":"Agility","verb":"crawl close enough to see them"}],"clueTitle":"Every head lifts","clueText":"Every one of them sits facing the doors. When the beat comes, every head lifts at once, and stays lifted until it has passed.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"5-5-3","place":"the shell of the house across the square","actions":[{"attr":"Agility","verb":"slip round to its back wall"},{"attr":"Aim","verb":"look in through the broken window"}],"clueTitle":"More bedrolls","clueText":"Round the fire lie more bedrolls than there are people at it, each one rolled tight and tied.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Where we could watch it, and watch him.\"* Why keep the two so close?","weekQuestion":"What will it take for the fifth to end this?","pull":"You stay in the rubble until full dark, and keep your watches there by turns, with the Order''s fire showing red through the gaps all night.\n\n**Counting down to what? You hold five pieces, and the trail began on the wall. The wall again.**"}'::jsonb),
('dark-moon', 1, 5, 6, '{"place":"The wall again","narrated":false,"tone":"wry","cupNight":false,"opener":"A slit window, a hidden room, a night nobody heard you.","questionTitle":"Why was this secret chamber hollowed into the rampart?","forkA":"To shelter the fifth Stone where no one could see it.","forkB":"To keep a perpetual watch on the doors of the hall.","callback":"Every map before tonight was read out loud. Tonight it went hand to hand, and nobody heard.","nudge":"{friend:Aim}, two smooth hollows where elbows rested, looking straight across at the king''s threshold. Who stood there?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Was this chamber meant for hiding or observing?","clickText":"From outside, the slit is hidden unless you lean over the abyss; but inside, the sill is worn smooth by a watcher''s elbows facing the hall. The room was built to observe."},"clicks":[{"a":"5-6-1","b":"5-6-2","text":"From outside, the slit is hidden unless you lean over the abyss; but inside, the sill is worn smooth by a watcher''s elbows facing the hall. The room was built to observe.","solves":true}],"riddle":null,"leads":[{"id":"5-6-1","place":"the city side of the wall, below the walk","actions":[{"attr":"Aim","verb":"lean out over the parapet"},{"attr":"Might","verb":"brace on the parapet and lean far out"}],"clueTitle":"The narrow slit","clueText":"The slit is no wider than a hand, low in the wall''s face. Unless you lean out over the parapet and look straight down the stone, you cannot see it at all.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-6-2","place":"the parapet on the city side","actions":[{"attr":"Craft","verb":"run a hand along the parapet''s top"},{"attr":"Might","verb":"lean your weight where others leaned"}],"clueTitle":"Two shallow dips","clueText":"Above where the map points, the parapet''s top is worn into two shallow dips, the width of a pair of elbows. They face the hall.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"5-6-3","place":"the forty paces of open stone","actions":[{"attr":"Agility","verb":"pace the walk while their heads are turned"},{"attr":"Intellect","verb":"measure the walk against the gate-tower"}],"clueTitle":"A stride wider","clueText":"Here the walk is wider than at the gate, by a good stride. All of the extra width is on the city side.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"Where he fell, under the dark moon, the five were joined.\"* Why there, and why that night?","weekQuestion":"What will it take for the fifth to end this?","pull":"**The watch has changed. It is dark enough. Into the wall, tonight.**"}'::jsonb)
insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 6, 1, '{"place":"The wall room (Six nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"Quiet''s good in a hole in a wall. I''ll take it.","questionTitle":"Did the watchman at the board see our shadow in the slit?","forkA":"Yes, he marked the wall room and will send searchers.","forkB":"No, he was looking at the rampart out of old habit.","callback":"At dusk you crossed the wall and nobody heard. By the end of the night a watchman was looking straight at your window.","nudge":"{friend:Aim}, he looked straight at the wall before he struck the board. Did he see us, or was he looking at the stone?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Could any candle inside the wall be seen from the square?","clickText":"The niche faces away from the slit and its soot is ancient; no light has been lit in this chamber tonight. Whatever the watchman looked toward, he saw no flame."},"clicks":[{"a":"6-1-1","b":"6-1-3","text":"The niche faces away from the slit and its soot is ancient; no light has been lit in this chamber tonight. Whatever the watchman looked toward, he saw no flame.","solves":true}],"riddle":null,"leads":[{"id":"6-1-1","place":"the slit, after dark","actions":[{"attr":"Aim","verb":"watch the lanterns from the slit"},{"attr":"Intellect","verb":"follow where each lantern goes"}],"clueTitle":"No light inside","clueText":"Not a candle burns in the room. Every lantern you can see from the slit is out in the square, and none of them reaches in.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-1-2","place":"the board in the square","actions":[{"attr":"Aim","verb":"watch the board from the slit at dusk"},{"attr":"Intellect","verb":"watch the man with the chalk, not the board"}],"clueTitle":"One look down the hill","clueText":"At dusk the watchman with the chalk stops before he strikes the board. He turns, looks down the hill at the wall, and then strikes it.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-1-3","place":"the stone niche where it lay","actions":[{"attr":"Craft","verb":"hold a hand inside and feel the stone"},{"attr":"Intellect","verb":"look at the niche with the lamp unlit"}],"clueTitle":"The old soot","clueText":"The back of the stone niche is blackened in one small round patch, the way a candle marks stone over years. The niche faces the inner wall, away from the slit.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"We let them go.\"* Why spare anyone, on a night like that?","weekQuestion":"What will the fifth do in his hall?","pull":"**The hall is sealed, and the Seekers left a way in, somewhere. The arrow points down: the defenders'' barracks, under the wall.**"}'::jsonb),
('dark-moon', 1, 6, 2, '{"place":"The barracks under the wall (Five nights)","narrated":false,"tone":"quiet","cupNight":false,"opener":null,"questionTitle":"Where are the garrison''s spears?","forkA":"Carried up to the hall for the waking.","forkB":"Confiscated long ago when the city fell.","callback":"Last week you couldn''t be sure a helm had turned toward you. Today one stood in your doorway and looked at the fallen stone instead.","nudge":"{friend:Agility}, empty racks swept clean, and bowls set out that were never filled. When did they leave?","nudgeIfLaid":null,"narratedSilence":"Garrick rests his head against the cold masonry, listening to the hollow thud of the earth below in silence.","puzzle":null,"clicks":[],"riddle":null,"leads":[{"id":"6-2-1","place":"where the spears once stood","actions":[{"attr":"Craft","verb":"look at the dust under the racks"},{"attr":"Intellect","verb":"walk the racks end to end"}],"clueTitle":"The swept racks","clueText":"The spear-racks along the wall are empty, and the dust under every one is swept clean in the same short arc.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-2-2","place":"the stair up to the street","actions":[{"attr":"Agility","verb":"climb to the top step and listen"},{"attr":"Intellect","verb":"count what you hear"}],"clueTitle":"Every foot at once","clueText":"When the heartbeat comes, you hear iron move all over the city at once: one scrape of a foot from every street, then quiet.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-2-3","place":"the kitchen whose fire went out","actions":[{"attr":"Craft","verb":"look over the board and the pot"},{"attr":"Might","verb":"lift the lid of the cold pot"}],"clueTitle":"Bowls never filled","clueText":"In the kitchen, bowls are set out along the board for a meal, and a ladle lies in the cold pot. Not one bowl was filled.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"That is how we found the shards.\"* How could a mark help anyone find one?","weekQuestion":"What will the fifth do in his hall?","pull":"**They are not coming for you. They are going to him. And wherever the Seekers'' way in begins, it begins at his walls. The great square, after dark.**"}'::jsonb),
('dark-moon', 1, 6, 3, '{"place":"The great square (Four nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"The hall''s warm from within. More faithful arriving. What''s missing is a door.","questionTitle":"How are the robed faithful entering the sealed hall?","forkA":"There is a hidden passage through the rock.","forkB":"The great bronze doors open for them at dusk.","callback":"The soldiers are three streets nearer the hall. Round the Order''s fire there are twice as many as before.","nudge":"{friend:Intellect}, clean robes in their packs, and not a footprint across the threshold of the bronze doors. Where did they go?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Have the main doors been unsealed?","clickText":"The dust along the threshold of the great doors has not been disturbed by a single breath, yet new men arrive with clean robes ready for the ceremony. They are entering through another way."},"clicks":[{"a":"6-3-1","b":"6-3-2","text":"The dust along the threshold of the great doors has not been disturbed by a single breath, yet new men arrive with clean robes ready for the ceremony. They are entering through another way.","solves":true}],"riddle":null,"leads":[{"id":"6-3-1","place":"the foot of the great doors","actions":[{"attr":"Agility","verb":"slip along the wall to the doors"},{"attr":"Craft","verb":"look at the ground under the seam"}],"clueTitle":"The unbroken drift","clueText":"At the foot of the great doors, dust has drifted against the seam in one smooth bank, from post to post. Nothing has crossed it.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"6-3-2","place":"the ruined house across from the hall","actions":[{"attr":"Aim","verb":"pick out what is stacked by their fire"},{"attr":"Agility","verb":"creep along the ruined house''s wall"}],"clueTitle":"Clean robes","clueText":"By the Order''s fire the new men''s packs are stacked in a row. On top of each lies a folded robe, brushed clean of the road.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"6-3-3","place":"the hall''s great wall","actions":[{"attr":"Craft","verb":"feel the stone, hand over hand"},{"attr":"Might","verb":"climb a little way and feel higher"}],"clueTitle":"Warm low down","clueText":"Move your palm up the wall and the stone cools. The warmth is only low down, at the height of your knee and below.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"None of us could bear to lift him.\"* What kept them from lifting him?","weekQuestion":"What will the fifth do in his hall?","pull":"You cross back on the change of the watch, while the two men are looking at each other, and sleep in the wall room with the warmth of that stone still in your palm.\n\n**He is on the other side of this wall. Inside, on the night the moon goes dark, with the fifth: that is the whole plan now. The cracked hill behind the hall.**"}'::jsonb),
('dark-moon', 1, 6, 4, '{"place":"The hill behind the hall (Three nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"That hill was steeper than it looked. Sit.","questionTitle":"Who posted the sentinel inside the rock fissure?","forkA":"The Seekers, to guard their secret entrance.","forkB":"The Order, to prevent anyone reaching the back of the hall.","callback":"Upriver, a dog on a chain kept the hidden path. Today a soldier stood in the crack with its back to the hall.","nudge":"{friend:Craft}, two hollows worn into solid stone by iron boots. That soldier was put there to stay.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How long has this sentinel guarded the cleft?","clickText":"The grit past the soldier was smooth until your own boots scuffed it, but the rock under its iron soles is worn deep into two foot-hollows. It has stood sentinel there since the war ended."},"clicks":[{"a":"6-4-1","b":"6-4-2","text":"The grit past the soldier was smooth until your own boots scuffed it, but the rock under its iron soles is worn deep into two foot-hollows. It has stood sentinel there since the war ended.","solves":true}],"riddle":null,"leads":[{"id":"6-4-1","place":"inside the crack, by lamplight","actions":[{"attr":"Agility","verb":"go in sideways, lamp first"},{"attr":"Aim","verb":"light the ground ahead and look"}],"clueTitle":"The untouched grit","clueText":"Past where the soldier stood, the grit on the crack''s floor lies smooth and untouched. Your boots are the first marks in it.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"6-4-2","place":"the soldier in the mouth of the crack","actions":[{"attr":"Might","verb":"drag the broken armour aside"},{"attr":"Craft","verb":"look at the rock it stood on"}],"clueTitle":"Two hollows","clueText":"The rock where it stood is worn into two shallow hollows, one for each foot. It stood on that one spot, facing out, for a very long time.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"6-4-3","place":"the blank rock at the dead end","actions":[{"attr":"Agility","verb":"squeeze on to the very end"},{"attr":"Charm","verb":"keep everyone quiet, and listen"}],"clueTitle":"Louder here","clueText":"Put your ear to the blank rock. When the heartbeat comes, it is louder here than anywhere else in the crack.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"Forgive us for leaving it at all.\"* Why would leaving a way in need forgiving?","weekQuestion":"What will the fifth do in his hall?","pull":"**What does a full moon struck dark mean? The moon-tower.**"}'::jsonb),
('dark-moon', 1, 6, 5, '{"place":"The moon-tower (Two nights)","narrated":false,"tone":"wry","cupNight":false,"opener":"Two nights. Eat while there''s something to eat.","questionTitle":"Did the sky-watchers foresee the night of the waking?","forkA":"Their calculations predicted the exact dark moon centuries in advance.","forkB":"Their records ended abruptly when the city fell, and the date is a coincidence.","callback":"The Order''s board has counted down for generations. The sky-watchers'' wall, counted forward, lands on the same night.","nudge":"{friend:Intellect}, slates with sums scratched out and begun again. What were they struggling to count?","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"How did their astronomical calculations conclude?","clickText":"Every moon on the wall was measured with exact discipline, but the slates on the floor are covered in frantic revisions and repeated sums. In the final days, their calculations were slipping away from them."},"clicks":[{"a":"6-5-1","b":"6-5-2","text":"Every moon on the wall was measured with exact discipline, but the slates on the floor are covered in frantic revisions and repeated sums. In the final days, their calculations were slipping away from them.","solves":true}],"riddle":null,"leads":[{"id":"6-5-1","place":"the sky-watchers'' wall, row by row","actions":[{"attr":"Intellect","verb":"measure the space between the moons"},{"attr":"Aim","verb":"follow one row all the way round"}],"clueTitle":"A finger''s width","clueText":"Lay a finger between any two moons, on any row. The space is the same every time, year on year, round the whole room.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-5-2","place":"the floor of the round room","actions":[{"attr":"Craft","verb":"gather up what lies on the floor"},{"attr":"Intellect","verb":"read the scratches by daylight"}],"clueTitle":"Sums begun again","clueText":"On the floor lie the sky-watchers'' slates, scratched with long sums. Many are crossed through and begun again.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"6-5-3","place":"where the rows stop","actions":[{"attr":"Might","verb":"climb the ledges to the last rows"},{"attr":"Craft","verb":"run a thumb along the last cuts"}],"clueTitle":"Cut in a hurry","clueText":"In the last rows before they stop, every moon is cut to the right depth, but the edges are rough, as if made in a hurry. Not one night is missing.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Be there when it does.\"* Be there to do what?","weekQuestion":"What will the fifth do in his hall?","pull":"**You have the hour. One piece is left, and the Seekers'' way ends at a blank rock with this same moon beside it. Tomorrow is the last day.**"}'::jsonb),
('dark-moon', 1, 6, 6, '{"place":"The crack in the hill (One night)","narrated":false,"tone":"wry","cupNight":true,"opener":"Last night of the count. Eat what you like.","questionTitle":"When the rock opens tomorrow, will the fifth Stone save the kingdom or doom it?","forkA":"It will bind the waking king and finish the Seekers'' work.","forkB":"It is the missing piece the Order needs to complete the waking.","callback":"Six nights ago you had a hidden room. Tonight you have one stroke left.","nudge":"{friend:Intellect}, every helm turned to the hall, and the streets behind us empty. Tomorrow night, we walk in.","nudgeIfLaid":null,"narratedSilence":null,"puzzle":{"q":"Is the way ahead clear of guards for tomorrow night?","clickText":"Every post across the lower streets has been abandoned, and every armoured helm on the hill is turned toward the hall. The entire city is converging on one room."},"clicks":[{"a":"6-6-1","b":"6-6-3","text":"Every post across the lower streets has been abandoned, and every armoured helm on the hill is turned toward the hall. The entire city is converging on one room.","solves":true}],"riddle":null,"leads":[{"id":"6-6-1","place":"the street below the crack","actions":[{"attr":"Aim","verb":"watch the street from the crack''s mouth"},{"attr":"Intellect","verb":"count the ranks as they climb"}],"clueTitle":"Every helm to the hall","clueText":"From the crack''s mouth you can see the whole street climbing toward you. Every helm in it is turned to the hall, not one to the hill.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-6-2","place":"the foot of the blank rock","actions":[{"attr":"Craft","verb":"look at how the grit lies"},{"attr":"Agility","verb":"get down low with the lamp"}],"clueTitle":"The swept fan","clueText":"At the foot of the blank rock, the old grit on your side lies swept flat in a smooth quarter-circle. Its point is at the rock''s left edge.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"6-6-3","place":"the streets you crossed this morning","actions":[{"attr":"Aim","verb":"look back down the hill from the crack"},{"attr":"Agility","verb":"go back the long way, street by street"}],"clueTitle":"Every post empty","clueText":"The crossroads, the gate-tower, the street under the wall: every place where a soldier stood is empty now. Only the pale marks of their boots are left.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"Finish what we could not.\"* What did the Seekers leave unfinished?","weekQuestion":"What will the fifth do in his hall?","pull":"**Tomorrow night, when the moon goes dark: through the Seekers'' door, into his hall, with the fifth in your hands.**"}'::jsonb)
